#define main historical_main
#include "../geglu-cuda/main.cu"
#undef main
#include <vector>
struct Case{float*input,*output;int rows,width;std::vector<float>expected;};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;if(repeat<1)return 2;std::vector<Case>cases;for(int width:{1280,2560,5120}){Case c;c.rows=128;c.width=width;std::vector<float>input(2*c.rows*width);for(int i=0;i<(int)input.size();i++)input[i]=float((i*17+3)%1025)/1024.f*12.f-6.f;c.expected.resize(c.rows*width);geglu_reference(c.expected.data(),input.data(),c.rows,width);CUDA_CHECK(cudaMalloc(&c.input,input.size()*sizeof(float)));CUDA_CHECK(cudaMalloc(&c.output,c.expected.size()*sizeof(float)));CUDA_CHECK(cudaMemcpy(c.input,input.data(),input.size()*sizeof(float),cudaMemcpyHostToDevice));geglu_gpu(c.output,c.input,c.rows,c.width);cases.push_back(c);}CUDA_CHECK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){double seconds=0,ma=0,times[3];std::vector<float>out;bool ok=true;int ci=0;for(auto&c:cases){CUDA_CHECK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)geglu_gpu(c.output,c.input,c.rows,c.width);CUDA_CHECK(cudaDeviceSynchronize());times[ci++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;seconds+=times[ci-1];std::vector<float>got(c.expected.size());CUDA_CHECK(cudaMemcpy(got.data(),c.output,got.size()*sizeof(float),cudaMemcpyDeviceToHost));for(int i=0;i<(int)got.size();i++){ma=fmax(ma,fabs(got[i]-c.expected[i]));ok&=std::isfinite(got[i])&&fabs(got[i]-c.expected[i])<=1e-3;}out.insert(out.end(),got.begin(),got.end());}allok&=ok;char file[80];sprintf(file,"geglu_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(out.data(),sizeof(float),out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"sum_three_supported_widths_full_erf_GeGLU_operator\",\"jit_excluded\":true,\"internal_repeats\":%d,\"width_times_seconds\":[%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",out.size(),ma,repeat,times[0],times[1],times[2],file,out.size());}for(auto&c:cases){CUDA_CHECK(cudaFree(c.input));CUDA_CHECK(cudaFree(c.output));}puts(allok?"PASS":"FAIL");return allok?0:1;}
